	sim_and  U0 (.a(a),  .b(b),  .y(n0));
	sim_or   U1 (.a(a),  .b(b),  .y(n1));
	sim_and  U2 (.a(n1), .b(c),  .y(n2));
	sim_or   U3 (.a(n0), .b(n2), .y(cout));
	sim_exor U4 (.a(a),  .b(b),  .y(n3));
	sim_exor U5 (.a(n3), .b(c),  .y(sout));
endmodule

